(()=>{
const menu=document.querySelector('.compact-menu-grid');if(!menu)return;
const trigger=document.createElement('button');trigger.textContent='📊 수입·기부 현황';menu.append(trigger);
const dialog=document.createElement('dialog');dialog.className='community-board';dialog.innerHTML='<div class="community-head"><h2>우리 반 수입·기부</h2><button aria-label="현황 닫기">×</button></div><p>학급 개설 이후 누적 기록이에요. 판매 수입에는 시작 코인·퀴즈 보상이 포함되지 않아요. 보유 코인이나 순이익과는 달라요.</p><p>기부는 공동 도시락·공동 식탁·협력 미션에 보탠 물건의 총수량이에요. 학생 화면에는 반 전체 합계와 내 기록만 보여요.</p><button class="community-refresh">새로고침</button><p class="community-status" role="status"></p><div class="community-content"></div>';document.body.append(dialog);
const style=document.createElement('style');style.textContent='.community-board{width:min(720px,calc(100% - 24px));max-height:85vh;box-sizing:border-box;border:0;border-radius:18px;padding:22px;color:#294b38;background:#f8faf5;overflow:auto}.community-board::backdrop{background:#132e3380}.community-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.community-head h2{margin:0;font-size:23px}.community-board p{font-size:14px;line-height:1.65}.community-board button{padding:10px 16px;min-height:42px;border:0;border-radius:9px;background:#e2eddf;color:#294b38;cursor:pointer}.community-totals{background:#295c49;color:white;border-radius:12px;padding:16px;margin-bottom:12px;font-size:16px;line-height:1.8}.community-people{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.community-person{border:1px solid #dce7d7;background:white;border-radius:12px;padding:14px;line-height:1.8;font-size:14px}.community-person b{display:block;font-size:16px}.community-person.mine{border:2px solid #43805b}@media(max-width:500px){.community-people{grid-template-columns:1fr}}';document.head.append(style);
const content=dialog.querySelector('.community-content'),status=dialog.querySelector('.community-status'),refresh=dialog.querySelector('.community-refresh');let loading=false;
dialog.querySelector('.community-head button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.querySelector('#compactMenuButton')?.focus());
async function load(){if(loading)return;const token=sessionStorage.getItem('village-student-token');content.replaceChildren();if(!token){status.textContent='학급 코드로 입장하면 우리 반 합계와 내 판매·기부 기록을 볼 수 있어요. 혼자 연습한 기록은 여기에 합쳐지지 않아요.';return}loading=true;refresh.disabled=true;status.textContent='우리 반 기록을 불러오는 중이에요…';try{const response=await fetch('/api/community',{headers:{authorization:'Bearer '+token},cache:'no-store',signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw Error(data.error||'기록을 불러오지 못했어요.');const totals=document.createElement('div');totals.className='community-totals';totals.textContent='우리 반 판매 수입 '+data.totals.sales.toLocaleString()+' 코인 · 함께 기부한 물건 '+data.totals.donated.toLocaleString()+'개';content.append(totals);const grid=document.createElement('div');grid.className='community-people';for(const p of data.players){const card=document.createElement('article');card.className='community-person'+(p.isMe?' mine':'');const name=document.createElement('b');name.textContent=p.name+(p.isMe?' · 나':'');const income=document.createElement('div');income.textContent='판매 수입 '+p.sales.toLocaleString()+' 코인';const donation=document.createElement('div');donation.textContent='기부한 물건 '+p.donated.toLocaleString()+'개';card.append(name,income,donation);grid.append(card)}content.append(grid);status.textContent=new Date(data.asOf).toLocaleTimeString('ko-KR')+' 기준 · 최신 기록은 새로고침을 눌러 확인해요.'}catch(error){status.textContent=error.name==='TimeoutError'?'연결이 늦어지고 있어요. 새로고침으로 다시 확인해 주세요.':error.message}finally{loading=false;refresh.disabled=false}}
refresh.onclick=load;trigger.onclick=()=>{document.querySelector('.compact-menu').close();dialog.showModal();load()};
})();
